SourceCode.Declaration:
/// <summary>
/// HSMobileOpsCountRequestSvc (10 Nov 2026). Three count types live in the Stock count control
/// center - Wall to wall, Hazard, Blind - and none starts with a journal: counts are staged per
/// counter (HSMobileOpsCountStageSvc), on-hand and variance are recorded as they arrive, and the
/// supervisor decides duplicates and creates the journal.
///
/// Outside system: createHazardCount, cancelHazardCount, getHazardCountStatus (privilege
/// HSMobileOpsCountRequestApi). Handheld: listCounts, getCountItems, getCountResults; cycle count
/// supervisor: listCategories, createCount.
/// </summary>
class HSMobileOpsCountRequestService
{
}

Method.Source:
/// <summary>
/// The outside system asks for a hazard count: warehouse, due time, items. Opens one control
/// center count of type Hazard with its requested items - no journal. The same Reference again
/// returns the count already made (Existing), unless that one was cancelled.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse createHazardCount(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse  response = new HSMobileOpsCountReqResponse();
    HSMobileOpsCountMaster       master;
    HSMobileOpsCountItem         item;
    System.Object                parsedObj;
    Newtonsoft.Json.Linq.JArray  jArray;
    Newtonsoft.Json.Linq.JObject jItem;
    List                         rows = new List(Types::Container);
    ListEnumerator               row;
    container                    values;
    utcdatetime                  due;
    str                          reference = _request ? strLTrim(strRTrim(_request.parmReference())) : '';
    str                          unknown;
    str                          itemId;
    str                          locationId;
    int                          unknownCount;
    int                          i;

    response.parmSuccess(false);
    if (!_request || !reference || !_request.parmWarehouseId() || !_request.parmItemsJson()
        || !_request.parmDataAreaId() || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('DataAreaId, Reference, WarehouseId and ItemsJson are required.');
        return response;
    }
    if (strLen(reference) > 50)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('Reference is longer than 50 characters.');
        return response;
    }
    due = HSMobileOpsCountRequestService::parseUtc(_request.parmDueUtc());
    if (_request.parmDueUtc() && due == utcDateTimeNull())
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('DueUtc must be a UTC date and time like 2026-11-10T14:00:00Z.');
        return response;
    }
    response.parmReference(reference);
    changecompany (_request.parmDataAreaId())
    {
        if (!InventLocation::find(_request.parmWarehouseId()).RecId)
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage(strFmt('Warehouse %1 does not exist in %2.', _request.parmWarehouseId(), _request.parmDataAreaId()));
            return response;
        }
        master = HSMobileOpsCountRequestService::findHazard(reference);
        if (master.RecId && master.Status != HSMobileOpsCountMasterStatus::Cancelled)
        {
            HSMobileOpsCountRequestService::describe(master, response);
            response.parmExisting(true);
            response.parmSuccess(true);
            response.parmMessage(strFmt('Reference %1 already has hazard count %2.', reference, master.MasterId));
            return response;
        }
        try
        {
            parsedObj = Newtonsoft.Json.Linq.JArray::Parse(_request.parmItemsJson());
        }
        catch (Exception::CLRError)
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage('ItemsJson is not a JSON array.');
            return response;
        }
        jArray = parsedObj;
        for (i = 0; jArray != null && i < jArray.get_Count(); i++)
        {
            jItem = jArray.get_Item(i);
            if (jItem == null)
            {
                continue;
            }
            itemId     = HSMobileOpsCountRequestService::jsonStr(jItem, 'ItemId');
            locationId = HSMobileOpsCountRequestService::jsonStr(jItem, 'LocationId');
            if (!itemId || !InventTable::exist(itemId)
                || (locationId && !WMSLocation::find(locationId, _request.parmWarehouseId()).RecId))
            {
                unknownCount++;
                if (unknownCount <= 10)
                {
                    unknown += (unknown ? ', ' : '') + (itemId ? itemId : '(no ItemId)') + (locationId ? ' at ' + locationId : '');
                }
                continue;
            }
            rows.addEnd([itemId, HSMobileOpsCountRequestService::jsonStr(jItem, 'ConfigId'),
                HSMobileOpsCountRequestService::jsonStr(jItem, 'SizeId'), HSMobileOpsCountRequestService::jsonStr(jItem, 'ColorId'),
                HSMobileOpsCountRequestService::jsonStr(jItem, 'StyleId'), locationId]);
        }
        if (unknownCount)
        {
            response.parmErrorCode('UNKNOWN_ITEMS');
            response.parmMessage(strFmt('%1 item(s) are not in D365FO (or their location is not in %2): %3. Nothing was created.',
                unknownCount, _request.parmWarehouseId(), unknown));
            return response;
        }
        if (!rows.elements())
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage('ItemsJson has no items.');
            return response;
        }

        ttsbegin;
        master = HSMobileOpsCountControl::newMaster(HSMobileOpsCountMasterType::Hazard, _request.parmWarehouseId(),
            _request.parmDescription() ? _request.parmDescription() : strFmt('Hazard count %1', reference), curUserId(), reference, due);
        row = rows.getEnumerator();
        while (row.moveNext())
        {
            values = row.current();
            item.clear();
            item.MasterRecId   = master.RecId;
            item.ItemId        = conPeek(values, 1);
            item.ConfigId      = conPeek(values, 2);
            item.InventSizeId  = conPeek(values, 3);
            item.InventColorId = conPeek(values, 4);
            item.InventStyleId = conPeek(values, 5);
            item.WMSLocationId = conPeek(values, 6);
            item.insert();
        }
        ttscommit;
        master = HSMobileOpsCountControl::masterOf(master.RecId);
        HSMobileOpsCountRequestService::describe(master, response);
        response.parmSuccess(true);
        response.parmMessage(strFmt('Hazard count %1 created with %2 item(s).', master.MasterId, master.RequestedItemCount));
    }
    return response;
}

/// <summary>
/// The outside system withdraws a hazard count. Only while no journal has been created.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse cancelHazardCount(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = HSMobileOpsCountRequestService::validateCompany(_request);
    HSMobileOpsCountMaster      master;

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        master = HSMobileOpsCountRequestService::findHazard(_request.parmReference());
        if (!master.RecId)
        {
            response.parmErrorCode('NOT_FOUND');
            response.parmMessage(strFmt('No hazard count has reference %1.', _request.parmReference()));
            return response;
        }
        if (master.Status == HSMobileOpsCountMasterStatus::Open)
        {
            HSMobileOpsCountControl::cancel(master.RecId);
            master = HSMobileOpsCountControl::masterOf(master.RecId);
        }
        HSMobileOpsCountRequestService::describe(master, response);
        if (master.Status != HSMobileOpsCountMasterStatus::Cancelled)
        {
            response.parmErrorCode('CANNOT_CANCEL');
            response.parmMessage(strFmt('%1 already has a counting journal - it can no longer be cancelled.', master.MasterId));
            return response;
        }
        response.parmSuccess(true);
    }
    return response;
}

/// <summary>
/// Where a hazard count is, and once its journal exists, what was counted against the on-hand.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse getHazardCountStatus(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = HSMobileOpsCountRequestService::validateCompany(_request);
    HSMobileOpsCountMaster      master;

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        master = HSMobileOpsCountRequestService::findHazard(_request.parmReference());
        if (!master.RecId)
        {
            response.parmErrorCode('NOT_FOUND');
            response.parmMessage(strFmt('No hazard count has reference %1.', _request.parmReference()));
            return response;
        }
        HSMobileOpsCountRequestService::describe(master, response);
        response.parmPayloadJson(HSMobileOpsCountRequestService::resultsJson(master));
        response.parmSuccess(true);
    }
    return response;
}

/// <summary>
/// The handheld's Count menu: the warehouse's open counts of every type, and those whose
/// journal was created in the last 7 days (their results). Newest first.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse listCounts(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse  response = HSMobileOpsCountRequestService::validateUser(_request);
    HSMobileOpsCountMaster       master;
    HSMobileOpsCountStage        stage;
    Newtonsoft.Json.Linq.JArray  counts = new Newtonsoft.Json.Linq.JArray();
    Newtonsoft.Json.Linq.JObject entry;
    utcdatetime                  since = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        while select master
            order by StartedUtc desc
            where master.InventLocationId == _request.parmWarehouseId()
               && master.Status          != HSMobileOpsCountMasterStatus::Cancelled
        {
            if (master.Status == HSMobileOpsCountMasterStatus::Transferred && master.TransferredUtc < since)
            {
                continue;
            }
            if (master.MasterType == HSMobileOpsCountMasterType::Blind && !master.RequestedItemCount)
            {
                continue;
            }
            select firstonly RecId, Status from stage
                where stage.MasterRecId == master.RecId
                   && stage.UserName    == _request.parmUserName();
            entry = new Newtonsoft.Json.Linq.JObject();
            HSMobileOpsCountRequestService::put(entry, 'MasterId', master.MasterId);
            HSMobileOpsCountRequestService::put(entry, 'Type', enum2Symbol(enumNum(HSMobileOpsCountMasterType), master.MasterType));
            HSMobileOpsCountRequestService::put(entry, 'Reference', master.ExternalRef);
            HSMobileOpsCountRequestService::put(entry, 'Description', master.Description);
            HSMobileOpsCountRequestService::put(entry, 'DueUtc', HSMobileOpsCountRequestService::isoUtc(master.DueUtc));
            HSMobileOpsCountRequestService::put(entry, 'StartedUtc', HSMobileOpsCountRequestService::isoUtc(master.StartedUtc));
            HSMobileOpsCountRequestService::put(entry, 'Status', HSMobileOpsCountRequestService::statusOf(master));
            HSMobileOpsCountRequestService::put(entry, 'JournalId', master.TransferredJournalId);
            HSMobileOpsCountRequestService::put(entry, 'ItemCount', int2Str(master.RequestedItemCount));
            HSMobileOpsCountRequestService::put(entry, 'CounterCount', int2Str(master.CounterCount));
            HSMobileOpsCountRequestService::put(entry, 'LineCount', int2Str(master.LineCount));
            HSMobileOpsCountRequestService::put(entry, 'MyStatus', stage.RecId ? enum2Symbol(enumNum(HSMobileOpsCountStageStatus), stage.Status) : '');
            counts.Add(entry);
        }
    }
    response.parmPayloadJson(counts.ToString());
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// What a hazard or blind count asks to be counted (empty for wall to wall).
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse getCountItems(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse  response = HSMobileOpsCountRequestService::validateUser(_request);
    HSMobileOpsCountMaster       master;
    HSMobileOpsCountItem         item;
    HSMobileOpsCountStageLine    stageLine;
    Newtonsoft.Json.Linq.JArray  items = new Newtonsoft.Json.Linq.JArray();
    Newtonsoft.Json.Linq.JObject row;
    RefRecId                     hierarchy;
    Map                          categories = new Map(Types::String, Types::String);

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        hierarchy = HSMobileOpsCountRequestService::retailHierarchy();
        master = HSMobileOpsCountMaster::find(_request.parmMasterId());
        if (!master.RecId)
        {
            response.parmErrorCode('COUNT_NOT_FOUND');
            return response;
        }
        while select item order by LineNum where item.MasterRecId == master.RecId
        {
            row = new Newtonsoft.Json.Linq.JObject();
            HSMobileOpsCountRequestService::put(row, 'LineNum', int2Str(item.LineNum));
            HSMobileOpsCountRequestService::put(row, 'ItemId', item.ItemId);
            HSMobileOpsCountRequestService::put(row, 'ItemName', item.ItemName);
            HSMobileOpsCountRequestService::put(row, 'ConfigId', item.ConfigId);
            HSMobileOpsCountRequestService::put(row, 'SizeId', item.InventSizeId);
            HSMobileOpsCountRequestService::put(row, 'ColorId', item.InventColorId);
            HSMobileOpsCountRequestService::put(row, 'StyleId', item.InventStyleId);
            HSMobileOpsCountRequestService::put(row, 'LocationId', item.WMSLocationId);
            // The supervisor's view (user, 10 Nov): first-level category of the retail product
            // hierarchy, and whether any counter has counted the item yet.
            if (!categories.exists(item.ItemId))
            {
                categories.insert(item.ItemId, HSMobileOpsCountRequestService::topCategory(item.ItemId, hierarchy));
            }
            HSMobileOpsCountRequestService::put(row, 'Category', categories.lookup(item.ItemId));
            if (item.WMSLocationId)
            {
                select firstonly RecId from stageLine
                    where stageLine.MasterRecId   == master.RecId
                       && stageLine.ItemId        == item.ItemId
                       && stageLine.WMSLocationId == item.WMSLocationId;
            }
            else
            {
                select firstonly RecId from stageLine
                    where stageLine.MasterRecId == master.RecId
                       && stageLine.ItemId      == item.ItemId;
            }
            HSMobileOpsCountRequestService::put(row, 'Counted', stageLine.RecId ? 'true' : 'false');
            items.Add(row);
        }
        HSMobileOpsCountRequestService::describe(master, response);
    }
    response.parmPayloadJson(items.ToString());
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// Counted, on-hand and variance per journal line, once the supervisor has created the journal.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse getCountResults(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = HSMobileOpsCountRequestService::validateUser(_request);
    HSMobileOpsCountMaster      master;

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        master = HSMobileOpsCountMaster::find(_request.parmMasterId());
        if (!master.RecId)
        {
            response.parmErrorCode('COUNT_NOT_FOUND');
            return response;
        }
        HSMobileOpsCountRequestService::describe(master, response);
        if (!master.TransferredJournalId)
        {
            response.parmErrorCode('NOT_READY');
            response.parmMessage(strFmt('%1 has no journal yet - results show once the supervisor creates it.', master.MasterId));
            return response;
        }
        response.parmPayloadJson(HSMobileOpsCountRequestService::resultsJson(master));
    }
    response.parmSuccess(true);
    return response;
}

private static str resultsJson(HSMobileOpsCountMaster _master)
{
    InventJournalTrans           journalTrans;
    InventDim                    inventDim;
    Newtonsoft.Json.Linq.JArray  rows = new Newtonsoft.Json.Linq.JArray();
    Newtonsoft.Json.Linq.JObject row;

    if (_master.TransferredJournalId)
    {
        while select journalTrans
            order by LineNum
            where journalTrans.JournalId == _master.TransferredJournalId
            join inventDim
                where inventDim.inventDimId == journalTrans.InventDimId
        {
            row = new Newtonsoft.Json.Linq.JObject();
            HSMobileOpsCountRequestService::put(row, 'ItemId', journalTrans.ItemId);
            HSMobileOpsCountRequestService::put(row, 'ItemName', InventTable::find(journalTrans.ItemId).defaultProductName());
            HSMobileOpsCountRequestService::put(row, 'ConfigId', inventDim.configId);
            HSMobileOpsCountRequestService::put(row, 'SizeId', inventDim.InventSizeId);
            HSMobileOpsCountRequestService::put(row, 'ColorId', inventDim.InventColorId);
            HSMobileOpsCountRequestService::put(row, 'StyleId', inventDim.InventStyleId);
            HSMobileOpsCountRequestService::put(row, 'BatchId', inventDim.inventBatchId);
            HSMobileOpsCountRequestService::put(row, 'SerialId', inventDim.inventSerialId);
            HSMobileOpsCountRequestService::put(row, 'LocationId', inventDim.wMSLocationId);
            HSMobileOpsCountRequestService::put(row, 'Counted', HSMobileOpsCountRequestService::num(journalTrans.Counted));
            HSMobileOpsCountRequestService::put(row, 'OnHand', HSMobileOpsCountRequestService::num(journalTrans.InventOnHand));
            HSMobileOpsCountRequestService::put(row, 'Variance', HSMobileOpsCountRequestService::num(journalTrans.Counted - journalTrans.InventOnHand));
            rows.Add(row);
        }
    }
    return rows.ToString();
}

private static void describe(HSMobileOpsCountMaster _master, HSMobileOpsCountReqResponse _response)
{
    _response.parmMasterId(_master.MasterId);
    _response.parmReference(_master.ExternalRef);
    _response.parmStatus(HSMobileOpsCountRequestService::statusOf(_master));
    _response.parmJournalId(_master.TransferredJournalId);
    _response.parmPosted(HSMobileOpsCountRequestService::isPosted(_master));
}

/// <summary>
/// Open (nobody counting yet), Counting, CreatingJournal, JournalCreated, Posted or Cancelled.
/// </summary>
private static str statusOf(HSMobileOpsCountMaster _master)
{
    switch (_master.Status)
    {
        case HSMobileOpsCountMasterStatus::Cancelled:
            return 'Cancelled';
        case HSMobileOpsCountMasterStatus::Transferring:
            return 'CreatingJournal';
        case HSMobileOpsCountMasterStatus::Transferred:
            return HSMobileOpsCountRequestService::isPosted(_master) ? 'Posted' : 'JournalCreated';
    }
    return _master.CounterCount ? 'Counting' : 'Open';
}

private static boolean isPosted(HSMobileOpsCountMaster _master)
{
    return _master.TransferredJournalId && InventJournalTable::find(_master.TransferredJournalId).Posted == NoYes::Yes;
}

/// <summary>
/// The newest hazard count with this reference. Called inside changecompany.
/// </summary>
private static HSMobileOpsCountMaster findHazard(str _reference)
{
    HSMobileOpsCountMaster master;

    if (_reference)
    {
        select firstonly master
            order by StartedUtc desc
            where master.MasterType  == HSMobileOpsCountMasterType::Hazard
               && master.ExternalRef == _reference;
    }
    return master;
}

private static HSMobileOpsCountReqResponse validateCompany(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = new HSMobileOpsCountReqResponse();

    response.parmSuccess(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmReference()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('DataAreaId and Reference are required.');
    }
    else
    {
        response.parmReference(_request.parmReference());
    }
    return response;
}

/// <summary>
/// The handheld's calls: an active mobile user of the company, and a warehouse or count.
/// </summary>
private static HSMobileOpsCountReqResponse validateUser(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = new HSMobileOpsCountReqResponse();
    HSMobileOpsUser             user;

    response.parmSuccess(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmUserName()
        || (!_request.parmWarehouseId() && !_request.parmMasterId())
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        user = HSMobileOpsUser::find(_request.parmUserName());
    }
    if (!user.RecId || !user.IsActive)
    {
        response.parmErrorCode('NOT_ALLOWED');
        response.parmMessage(strFmt('%1 is not an active mobile user', _request.parmUserName()));
    }
    return response;
}

/// <summary>
/// 2026-11-10T14:00:00Z (or without the Z, or with fractions) as a UTC date and time; empty
/// or unreadable gives the null value.
/// </summary>
private static utcdatetime parseUtc(str _value)
{
    str         value = strLTrim(strRTrim(_value));
    utcdatetime result = utcDateTimeNull();

    if (strLen(value) < 19)
    {
        return result;
    }
    value = subStr(value, 1, 19);
    try
    {
        result = DateTimeUtil::parse(value);
    }
    catch
    {
        result = utcDateTimeNull();
    }
    return result;
}

private static str isoUtc(utcdatetime _value)
{
    return _value == utcDateTimeNull() ? '' : DateTimeUtil::toStr(_value) + 'Z';
}

private static str num(real _value)
{
    return num2Str(_value, 0, 6, DecimalSeparator::Dot, ThousandSeparator::None);
}

private static void put(Newtonsoft.Json.Linq.JObject _obj, str _name, str _value)
{
    _obj.Add(_name, new Newtonsoft.Json.Linq.JValue(_value));
}

/// <summary>
/// Supervisor, creating a count (user, 10 Nov): the retail product hierarchy's categories under
/// CategoryId (blank = first level), A to Z, each with whether it has sub-categories.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse listCategories(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse  response = HSMobileOpsCountRequestService::validateSupervisor(_request);
    TableId                      categoryTable = tableName2Id('EcoResCategory');
    Newtonsoft.Json.Linq.JArray  rows = new Newtonsoft.Json.Linq.JArray();
    Newtonsoft.Json.Linq.JObject row;
    Query                        query;
    QueryBuildDataSource         ds;
    QueryRun                     queryRun;
    Common                       category;
    RefRecId                     hierarchy;
    RefRecId                     parent = str2Int64(_request ? _request.parmCategoryId() : '');

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        hierarchy = HSMobileOpsCountRequestService::retailHierarchy();
        if (!hierarchy || !categoryTable)
        {
            response.parmErrorCode('NO_HIERARCHY');
            response.parmMessage('No retail product hierarchy is set up.');
            return response;
        }
        query = new Query();
        ds = query.addDataSource(categoryTable);
        ds.addRange(fieldName2Id(categoryTable, 'CategoryHierarchy')).value(queryValue(hierarchy));
        if (parent)
        {
            ds.addRange(fieldName2Id(categoryTable, 'ParentCategory')).value(queryValue(parent));
        }
        else
        {
            ds.addRange(fieldName2Id(categoryTable, 'Level')).value(queryValue(2));
        }
        ds.addSortField(fieldName2Id(categoryTable, 'Name'));
        queryRun = new QueryRun(query);
        while (queryRun.next())
        {
            category = queryRun.get(categoryTable);
            row = new Newtonsoft.Json.Linq.JObject();
            HSMobileOpsCountRequestService::put(row, 'CategoryId', int642Str(category.RecId));
            HSMobileOpsCountRequestService::put(row, 'Name', category.(fieldName2Id(categoryTable, 'Name')));
            HSMobileOpsCountRequestService::put(row, 'HasChildren',
                HSMobileOpsCountRequestService::hasChildCategory(category.RecId) ? 'true' : 'false');
            // Released items of the company in it and its sub-categories (user, 11 Nov).
            HSMobileOpsCountRequestService::put(row, 'ItemCount',
                int642Str(HSMobileOpsCountRequestService::categoryItemCount(category, hierarchy)));
            rows.Add(row);
        }
    }
    response.parmPayloadJson(rows.ToString());
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// Supervisor, from the handheld (user, 10 Nov): one Stock count control center record of type
/// Blind, Hazard or Wall to wall for the warehouse, seen by every counter of it in the Count menu.
/// Blind and hazard: the items of the chosen categories (all of them, stocked here or not, with
/// their sub-categories) plus the chosen items. Wall to wall: joins the warehouse's open one.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountReqResponse createCount(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse  response = HSMobileOpsCountRequestService::validateSupervisor(_request);
    HSMobileOpsCountMaster       master;
    HSMobileOpsCountItem         item;
    HSMobileOpsCountMasterType   type;
    Set                          itemIds = new Set(Types::String);
    SetEnumerator                itemEnum;
    Newtonsoft.Json.Linq.JArray  jArray;
    Newtonsoft.Json.Linq.JObject jItem;
    System.Object                parsed;
    RefRecId                     hierarchy;
    str                          itemId;
    str                          unknown;
    str                          countType = _request ? _request.parmCountType() : '';
    int                          unknownCount;
    int                          i;
    LineNum                      lineNum;

    if (response.parmErrorCode())
    {
        return response;
    }
    switch (countType)
    {
        case 'Blind':      type = HSMobileOpsCountMasterType::Blind;      break;
        case 'Hazard':     type = HSMobileOpsCountMasterType::Hazard;     break;
        case 'WallToWall': type = HSMobileOpsCountMasterType::WallToWall; break;
        default:
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage('CountType must be Blind, Hazard or WallToWall.');
            return response;
    }
    if (!_request.parmWarehouseId())
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('WarehouseId is required.');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        if (!InventLocation::find(_request.parmWarehouseId()).RecId)
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage(strFmt('Warehouse %1 does not exist.', _request.parmWarehouseId()));
            return response;
        }
        if (type == HSMobileOpsCountMasterType::WallToWall)
        {
            select firstonly RecId from master
                where master.InventLocationId == _request.parmWarehouseId()
                   && master.SourceJournalId  == ''
                   && master.MasterType       == HSMobileOpsCountMasterType::WallToWall
                   && master.Status           == HSMobileOpsCountMasterStatus::Open;
            response.parmExisting(master.RecId != 0);
            ttsbegin;
            master = HSMobileOpsCountControl::openMaster(_request.parmWarehouseId(), '', _request.parmUserName());
            ttscommit;
            HSMobileOpsCountRequestService::describe(master, response);
            response.parmSuccess(true);
            response.parmMessage(strFmt('Wall to wall count %1 is open.', master.MasterId));
            return response;
        }

        hierarchy = HSMobileOpsCountRequestService::retailHierarchy();
        if (_request.parmCategoriesJson())
        {
            try
            {
                parsed = Newtonsoft.Json.Linq.JArray::Parse(_request.parmCategoriesJson());
            }
            catch (Exception::CLRError)
            {
                response.parmErrorCode('INVALID_REQUEST');
                response.parmMessage('CategoriesJson is not a JSON array.');
                return response;
            }
            jArray = parsed;
            for (i = 0; jArray != null && i < jArray.get_Count(); i++)
            {
                HSMobileOpsCountRequestService::addCategoryItems(str2Int64(jArray.get_Item(i).ToString()), hierarchy, itemIds);
            }
        }
        if (_request.parmItemsJson())
        {
            try
            {
                parsed = Newtonsoft.Json.Linq.JArray::Parse(_request.parmItemsJson());
            }
            catch (Exception::CLRError)
            {
                response.parmErrorCode('INVALID_REQUEST');
                response.parmMessage('ItemsJson is not a JSON array.');
                return response;
            }
            jArray = parsed;
            for (i = 0; jArray != null && i < jArray.get_Count(); i++)
            {
                jItem  = jArray.get_Item(i);
                itemId = jItem ? HSMobileOpsCountRequestService::jsonStr(jItem, 'ItemId') : '';
                if (!itemId || !InventTable::exist(itemId))
                {
                    unknownCount++;
                    if (unknownCount <= 10)
                    {
                        unknown += (unknown ? ', ' : '') + (itemId ? itemId : '(no ItemId)');
                    }
                    continue;
                }
                itemIds.add(itemId);
            }
        }
        if (unknownCount)
        {
            response.parmErrorCode('UNKNOWN_ITEMS');
            response.parmMessage(strFmt('%1 item(s) are not in D365FO: %2. Nothing was created.', unknownCount, unknown));
            return response;
        }
        if (!itemIds.elements())
        {
            response.parmErrorCode('NO_ITEMS');
            response.parmMessage('Pick at least one category with items, or an item.');
            return response;
        }

        ttsbegin;
        master = HSMobileOpsCountControl::newMaster(type, _request.parmWarehouseId(),
            _request.parmDescription() ? _request.parmDescription()
                : strFmt('%1 count by %2', type == HSMobileOpsCountMasterType::Hazard ? 'Hazard' : 'Blind', _request.parmUserName()),
            _request.parmUserName());
        // doInsert: numbered here and counted once below, not per row (a category can hold thousands).
        itemEnum = itemIds.getEnumerator();
        while (itemEnum.moveNext())
        {
            lineNum++;
            item.clear();
            item.MasterRecId = master.RecId;
            item.LineNum     = lineNum;
            item.ItemId      = itemEnum.current();
            item.ItemName    = subStr(InventTable::find(item.ItemId).defaultProductName(), 1, 60);
            item.doInsert();
        }
        ttscommit;
        HSMobileOpsCountItem::recount(master.RecId);
        master = HSMobileOpsCountControl::masterOf(master.RecId);
        HSMobileOpsCountRequestService::describe(master, response);
        response.parmSuccess(true);
        response.parmMessage(strFmt('%1 created with %2 item(s).', master.MasterId, master.RequestedItemCount));
    }
    return response;
}

/// <summary>
/// The handheld user must be an active cycle count supervisor.
/// </summary>
private static HSMobileOpsCountReqResponse validateSupervisor(HSMobileOpsCountReqRequest _request)
{
    HSMobileOpsCountReqResponse response = HSMobileOpsCountRequestService::validateUser(_request);
    HSMobileOpsUser             user;

    if (response.parmErrorCode())
    {
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        user = HSMobileOpsUser::find(_request.parmUserName());
    }
    if (!HSMobileOpsCountDualEngine::isSupervisor(user))
    {
        response.parmErrorCode('NOT_SUPERVISOR');
        response.parmMessage(strFmt('%1 is not a cycle count supervisor.', _request.parmUserName()));
    }
    return response;
}

/// <summary>
/// How many released items of the company sit in the category or its sub-categories - one
/// counting query (tables read by name: Retail extends them).
/// </summary>
private static int64 categoryItemCount(Common _category, RefRecId _hierarchy)
{
    TableId              categoryTable = tableName2Id('EcoResCategory');
    TableId              productCategoryTable = tableName2Id('EcoResProductCategory');
    Query                query = new Query();
    QueryBuildDataSource dsCategory;
    QueryBuildDataSource dsProduct;
    QueryBuildDataSource dsItem;
    QueryRun             queryRun;
    InventTable          inventTable;

    dsCategory = query.addDataSource(categoryTable);
    dsCategory.fields().dynamic(NoYes::No);
    dsCategory.fields().clearFieldList();
    dsCategory.addRange(fieldName2Id(categoryTable, 'CategoryHierarchy')).value(queryValue(_hierarchy));
    dsCategory.addRange(fieldName2Id(categoryTable, 'NestedSetLeft')).value(
        SysQuery::range(_category.(fieldName2Id(categoryTable, 'NestedSetLeft')), ''));
    dsCategory.addRange(fieldName2Id(categoryTable, 'NestedSetRight')).value(
        SysQuery::range('', _category.(fieldName2Id(categoryTable, 'NestedSetRight'))));
    dsProduct = dsCategory.addDataSource(productCategoryTable);
    dsProduct.joinMode(JoinMode::InnerJoin);
    dsProduct.fields().dynamic(NoYes::No);
    dsProduct.fields().clearFieldList();
    dsProduct.addLink(fieldName2Id(categoryTable, 'RecId'), fieldName2Id(productCategoryTable, 'Category'));
    dsProduct.addRange(fieldName2Id(productCategoryTable, 'CategoryHierarchy')).value(queryValue(_hierarchy));
    dsItem = dsProduct.addDataSource(tableNum(InventTable));
    dsItem.joinMode(JoinMode::InnerJoin);
    dsItem.fields().dynamic(NoYes::No);
    dsItem.fields().clearFieldList();
    dsItem.addLink(fieldName2Id(productCategoryTable, 'Product'), fieldNum(InventTable, Product));
    dsItem.addSelectionField(fieldNum(InventTable, RecId), SelectionField::Count);
    queryRun = new QueryRun(query);
    if (!queryRun.next())
    {
        return 0;
    }
    inventTable = queryRun.get(tableNum(InventTable));
    return inventTable.RecId;
}

private static boolean hasChildCategory(RefRecId _category)
{
    TableId              categoryTable = tableName2Id('EcoResCategory');
    Query                query = new Query();
    QueryBuildDataSource ds = query.addDataSource(categoryTable);
    QueryRun             queryRun;

    ds.firstOnly(true);
    ds.addRange(fieldName2Id(categoryTable, 'ParentCategory')).value(queryValue(_category));
    queryRun = new QueryRun(query);
    return queryRun.next();
}

/// <summary>
/// Every released item of the company in the category or its sub-categories (read by name:
/// Retail extends EcoResCategory and EcoResProductCategory).
/// </summary>
private static void addCategoryItems(RefRecId _category, RefRecId _hierarchy, Set _itemIds)
{
    TableId              categoryTable = tableName2Id('EcoResCategory');
    TableId              productCategoryTable = tableName2Id('EcoResProductCategory');
    Query                query;
    QueryBuildDataSource dsCategory;
    QueryBuildDataSource dsProduct;
    QueryRun             queryRun;
    Common               category;
    Common               productCategory;
    InventTable          inventTable;
    RefRecId             product;

    if (!_category || !_hierarchy)
    {
        return;
    }
    query = new Query();
    dsCategory = query.addDataSource(categoryTable);
    dsCategory.addRange(fieldName2Id(categoryTable, 'RecId')).value(queryValue(_category));
    queryRun = new QueryRun(query);
    if (!queryRun.next())
    {
        return;
    }
    category = queryRun.get(categoryTable);

    query = new Query();
    dsCategory = query.addDataSource(categoryTable);
    dsCategory.addRange(fieldName2Id(categoryTable, 'CategoryHierarchy')).value(queryValue(_hierarchy));
    dsCategory.addRange(fieldName2Id(categoryTable, 'NestedSetLeft')).value(
        SysQuery::range(category.(fieldName2Id(categoryTable, 'NestedSetLeft')), ''));
    dsCategory.addRange(fieldName2Id(categoryTable, 'NestedSetRight')).value(
        SysQuery::range('', category.(fieldName2Id(categoryTable, 'NestedSetRight'))));
    dsProduct = dsCategory.addDataSource(productCategoryTable);
    dsProduct.joinMode(JoinMode::InnerJoin);
    dsProduct.addLink(fieldName2Id(categoryTable, 'RecId'), fieldName2Id(productCategoryTable, 'Category'));
    dsProduct.addRange(fieldName2Id(productCategoryTable, 'CategoryHierarchy')).value(queryValue(_hierarchy));
    queryRun = new QueryRun(query);
    while (queryRun.next())
    {
        productCategory = queryRun.get(productCategoryTable);
        product = productCategory.(fieldName2Id(productCategoryTable, 'Product'));
        select firstonly ItemId from inventTable where inventTable.Product == product;
        if (inventTable.ItemId)
        {
            _itemIds.add(inventTable.ItemId);
        }
    }
}

/// <summary>
/// The company's retail product hierarchy - where an item's category for the supervisor comes from.
/// </summary>
private static RefRecId retailHierarchy()
{
    EcoResCategoryHierarchyRole role;

    select firstonly CategoryHierarchy from role
        where role.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Retail;
    return role.CategoryHierarchy;
}

/// <summary>
/// The item's first-level category (the level under the hierarchy's root), e.g. Health Care;
/// blank when the item is not in the hierarchy.
/// </summary>
private static str topCategory(ItemId _itemId, RefRecId _hierarchy)
{
    // EcoResProductCategory and EcoResCategory are read by name: Retail extends both tables,
    // and a compiled reference would make this model depend on Retail.
    InventTable           inventTable = InventTable::find(_itemId);
    TableId               productCategoryTable = tableName2Id('EcoResProductCategory');
    TableId               categoryTable = tableName2Id('EcoResCategory');
    Common                productCategory;
    RefRecId              categoryRecId;
    Common                leaf;
    Common                top;
    Query                 query;
    QueryBuildDataSource  ds;
    QueryRun              queryRun;
    int                   level;

    if (!_hierarchy || !inventTable.Product || !categoryTable || !productCategoryTable)
    {
        return '';
    }
    query = new Query();
    ds = query.addDataSource(productCategoryTable);
    ds.firstOnly(true);
    ds.addRange(fieldName2Id(productCategoryTable, 'Product')).value(queryValue(inventTable.Product));
    ds.addRange(fieldName2Id(productCategoryTable, 'CategoryHierarchy')).value(queryValue(_hierarchy));
    queryRun = new QueryRun(query);
    if (!queryRun.next())
    {
        return '';
    }
    productCategory = queryRun.get(productCategoryTable);
    categoryRecId   = productCategory.(fieldName2Id(productCategoryTable, 'Category'));
    if (!categoryRecId)
    {
        return '';
    }
    query = new Query();
    ds = query.addDataSource(categoryTable);
    ds.addRange(fieldName2Id(categoryTable, 'RecId')).value(queryValue(categoryRecId));
    queryRun = new QueryRun(query);
    if (!queryRun.next())
    {
        return '';
    }
    leaf  = queryRun.get(categoryTable);
    level = leaf.(fieldName2Id(categoryTable, 'Level'));
    if (level < 2)
    {
        return '';
    }
    if (level == 2)
    {
        return leaf.(fieldName2Id(categoryTable, 'Name'));
    }
    query = new Query();
    ds = query.addDataSource(categoryTable);
    ds.firstOnly(true);
    ds.addRange(fieldName2Id(categoryTable, 'CategoryHierarchy')).value(queryValue(leaf.(fieldName2Id(categoryTable, 'CategoryHierarchy'))));
    ds.addRange(fieldName2Id(categoryTable, 'Level')).value(queryValue(2));
    ds.addRange(fieldName2Id(categoryTable, 'NestedSetLeft')).value(SysQuery::range('', leaf.(fieldName2Id(categoryTable, 'NestedSetLeft'))));
    ds.addRange(fieldName2Id(categoryTable, 'NestedSetRight')).value(SysQuery::range(leaf.(fieldName2Id(categoryTable, 'NestedSetRight')), ''));
    queryRun = new QueryRun(query);
    if (!queryRun.next())
    {
        return '';
    }
    top = queryRun.get(categoryTable);
    return top.(fieldName2Id(categoryTable, 'Name'));
}

private static str jsonStr(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    Newtonsoft.Json.Linq.JToken token;

    if (_obj == null)
    {
        return '';
    }
    token = _obj.get_Item(_property);
    if (token == null)
    {
        return '';
    }
    return strLTrim(strRTrim(token.ToString()));
}
